{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Octreotide, a cyclic octapeptide, had an absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers after an 8 mg capsule, directly demonstrating that peptide drugs of this class have F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "GHRP-6, a hexapeptide, showed systemic availability of ~0.3% after oral administration in a clinical phase I study, supporting very low oral bioavailability for peptide drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "The hexapeptide HEX had a human oral bioavailability of 0.3 ± 0.1%, much lower than intranasal delivery, consistent with negligible oral absorption of peptides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor, had 0.5% oral bioavailability in humans at 40 mg p.o., showing that even smaller peptidomimetics fail to reach 20% F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "CGP 38 560, a peptidomimetic renin inhibitor, had <1% oral bioavailability in humans at 200 mg p.o., further supporting very low oral absorption for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Plecanatide, a peptide, exhibited negligible systemic availability after oral dosing, with plasma levels below the limit of quantitation, reinforcing the poor oral absorption of large peptides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Paliperidone ER had 28% absolute oral bioavailability in humans, but this high value comes from a small non-peptide molecule and is poorly transferable to the large peptide query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Macimorelin, a small-molecule ghrelin agonist, was reported to have good oral bioavailability in patients, but it is a small molecule rather than a large peptide and is not representative of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large acylated/PEGylated peptide. Direct human oral bioavailability data for peptide and peptidomimetic drugs—octreotide 0.6%, GHRP-6 ~0.3%, HEX 0.3%, enalkiren 0.5%, CGP 38 560 <1%, and plecanatide negligible—consistently show F < 20%. The few high-F small molecules (paliperidone, macimorelin) are not transferable to this peptide size and polarity. Therefore the prediction is low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself in the provided evidence.",
    "Most supporting analogues are smaller peptides/peptidomimetics; the query's long fatty-acid/PEG side chain and larger size may further limit absorption, but this is not directly measured here.",
    "Paliperidone has the highest Morgan similarity but is a small non-peptide molecule, limiting its relevance to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

